import System.Text.*;import System.ArgumentException;import System.Exception;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
class UnicodeCustomFallbackMaxCountBoundsProbe {
 static class E extends EncoderFallback{int maximum,reads,factories;E(int m){maximum=m;}public int get_MaxCharCount(){reads++;return maximum;}public EncoderFallbackBuffer CreateFallbackBuffer(){factories++;return new EncoderReplacementFallback("?").CreateFallbackBuffer();}}
 static class D extends DecoderFallback{int maximum,reads,factories;D(int m){maximum=m;}public int get_MaxCharCount(){reads++;return maximum;}public DecoderFallbackBuffer CreateFallbackBuffer(){factories++;return new DecoderReplacementFallback("?").CreateFallbackBuffer();}}
 static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 public static void main(String[] args)throws java.lang.Exception{int calls=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);E ef=new E(Integer.parseInt(p[1]));D df=new D(Integer.parseInt(p[1]));UnicodeEncoding e=(UnicodeEncoding)new UnicodeEncoding(p[0].equals("1"),true,false).Clone();e.set_EncoderFallback(ef);e.set_DecoderFallback(df);
 try{int value=p[4].equals("GetMaxByteCount")?e.GetMaxByteCount(Integer.parseInt(p[5])):e.GetMaxCharCount(Integer.parseInt(p[5]));check(p[7].isEmpty()&&value==Integer.parseInt(p[6]),"value "+line+" actual="+value);}catch(Exception ex){String message=new String(Base64.getDecoder().decode(p[8]),StandardCharsets.UTF_8);check(ex.getClass().getName().equals(p[7])&&ex.get_Message().equals(message)&&ex.get_HResult()==Integer.parseInt(p[9])&&Objects.equals(ex instanceof ArgumentException a?a.get_ParamName():null,p[10].equals("~")?null:p[10]),"failure "+line+" actual="+ex.get_Message());}check(ef.reads==Integer.parseInt(p[11])&&df.reads==Integer.parseInt(p[12])&&ef.factories==Integer.parseInt(p[13])&&df.factories==Integer.parseInt(p[14]),"callback calls "+line+" actual="+ef.reads+","+df.reads+","+ef.factories+","+df.factories);calls++;
 }java.lang.System.out.println("PASS Unicode replacement maximum-count calls="+calls);}
}
